static fractal_workspace_id id(uint64_t x){fractal_workspace_id r={0,x};return r;}
static fractal_compatibility_client_hello client(void){fractal_compatibility_client_hello c={0};c.contract_version=1;c.protocol_family=(fractal_version_range){1,3};c.message_schema=(fractal_version_range){1,2};c.workspace_contract=(fractal_version_range){1,1};c.pairing_contract=(fractal_version_range){1,1};c.features[0]=(fractal_feature){FRACTAL_FEATURE_PREVIEW_FULL_FRAME,1,false};c.features[1]=(fractal_feature){FRACTAL_FEATURE_ARTIFACT_BMP,1,true};c.feature_count=2;c.platform_class=FRACTAL_PLATFORM_ANDROID;return c;}
static fractal_compatibility_service_hello service(void){fractal_compatibility_service_hello s={0};s.contract_version=1;s.protocol_family=(fractal_version_range){2,4};s.message_schema=(fractal_version_range){2,3};s.workspace_contract=(fractal_version_range){1,1};s.pairing_contract=(fractal_version_range){1,1};s.minimum_supported_client_contract=1;s.features[0]=(fractal_feature){FRACTAL_FEATURE_ARTIFACT_BMP,1,false};s.feature_count=1;s.service_compatibility_epoch=7;s.service_restart_epoch=9;return s;}
int main(void){fractal_compatibility_client_hello c=client();fractal_compatibility_service_hello s=service();fractal_compatibility_selection sel=fractal_compatibility_negotiate(&c,&s);CHECK(sel.result==FRACTAL_COMPATIBLE);CHECK(sel.selected_protocol_family==3&&sel.selected_schema_version==2);CHECK(sel.feature_count==1&&sel.features[0].id==FRACTAL_FEATURE_ARTIFACT_BMP);s.protocol_family=(fractal_version_range){4,5};CHECK(fractal_compatibility_negotiate(&c,&s).result==FRACTAL_NO_COMMON_PROTOCOL);s=service();c.features[0]=(fractal_feature){FRACTAL_FEATURE_PREVIEW_TILE,1,true};CHECK(fractal_compatibility_negotiate(&c,&s).result==FRACTAL_CAPABILITY_MISMATCH);CHECK(fractal_connection_reduce(FRACTAL_CONN_UNINITIALIZED,FRACTAL_EVENT_APP_START).resulting_state==FRACTAL_CONN_DISCONNECTED);CHECK(fractal_connection_reduce(FRACTAL_CONN_CONNECTING,FRACTAL_EVENT_TRANSPORT_ESTABLISHED).resulting_state==FRACTAL_CONN_NEGOTIATING);CHECK(fractal_connection_reduce(FRACTAL_CONN_AUTHENTICATING,FRACTAL_EVENT_AUTHENTICATION_ACCEPTED).resulting_state==FRACTAL_CONN_REACQUIRING);CHECK(fractal_connection_reduce(FRACTAL_CONN_SYNCHRONIZED,FRACTAL_EVENT_NETWORK_LOST).resulting_state==FRACTAL_CONN_DISCONNECTED);CHECK(fractal_connection_reduce(FRACTAL_CONN_SYNCHRONIZED,FRACTAL_EVENT_APP_BACKGROUND).resulting_state==FRACTAL_CONN_SUSPENDED);CHECK(fractal_connection_reduce(FRACTAL_CONN_SUSPENDED,FRACTAL_EVENT_APP_FOREGROUND).resulting_state==FRACTAL_CONN_DISCONNECTED);fractal_retry_policy p={2,10,100,FRACTAL_BACKOFF_EXPONENTIAL,0,1000,true,false,false};CHECK(fractal_retry_evaluate(p,FRACTAL_RETRY_BACKOFF,0,true).delay_ticks==40);CHECK(!fractal_retry_evaluate(p,FRACTAL_PERMANENT_REVOCATION,0,true).retry);fractal_reacquire_response rr={0};rr.kind=FRACTAL_REACQUIRE_FULL_SNAPSHOT;rr.current_generation=5;rr.preview_identity=6;rr.preview_checksum=7;CHECK(fractal_reacquire_reduce(FRACTAL_REACQUIRE_REQUESTED,&rr).state==FRACTAL_REACQUIRE_SYNCHRONIZED);CHECK(fractal_preview_cache_valid(5,6,7,&rr));CHECK(!fractal_preview_cache_valid(4,6,7,&rr));CHECK(fractal_artifact_cache_valid(1,2,1,2));fractal_replay_cache cache;fractal_replay_cache_init(&cache,10);fractal_client_intent in={0};in.participant_id=id(1);in.command_sequence=10;in.identity=id(2);fractal_workspace_transition tr={true,true,false,1,2,1,FRACTAL_REJECT_NONE};CHECK(fractal_replay_cache_apply(&cache,&in,77,tr).kind==FRACTAL_REPLAY_NEW_ACCEPTED);CHECK(fractal_replay_cache_apply(&cache,&in,77,tr).kind==FRACTAL_REPLAY_IDENTICAL_RESULT);in.identity=id(3);CHECK(fractal_replay_cache_apply(&cache,&in,77,tr).kind==FRACTAL_COMMAND_SEQUENCE_CONFLICT);in.command_sequence=9;CHECK(fractal_replay_cache_apply(&cache,&in,77,tr).kind==FRACTAL_REPLAY_HISTORY_EXPIRED);fractal_fake_transport ft;fractal_fake_transport_event ev;fractal_fake_transport_init(&ft);CHECK(fractal_fake_transport_push(&ft,FRACTAL_FAKE_CONNECTION_ESTABLISHED)==0);CHECK(fractal_fake_transport_push(&ft,FRACTAL_FAKE_ACK_LOST)==0);CHECK(fractal_fake_transport_push(&ft,FRACTAL_FAKE_SERVICE_RESTART)==0);CHECK(fractal_fake_transport_step(&ft,&ev)==1&&ft.status==FRACTAL_TRANSPORT_READY);CHECK(fractal_fake_transport_step(&ft,&ev)==1&&ft.ack_lost);CHECK(fractal_fake_transport_step(&ft,&ev)==1&&ft.service_restart_epoch==1&&ft.status==FRACTAL_TRANSPORT_CLOSED);CHECK(sizeof(fractal_platform_frame)==1028);return 0;}
